--- layout/page ---
import type { Metadata, Viewport } from "next";
import { GeistSans } from "geist/font/sans";
import { GeistMono } from "geist/font/mono";
import { Caveat, IBM_Plex_Serif } from "next/font/google";
import { Analytics } from "@vercel/analytics/next";
import { SpeedInsights } from "@vercel/speed-insights/next";
import { CommandPaletteProvider } from "@/components/command-palette";
import { MobileDock } from "@/components/mobile-dock";
import { ThemeColor } from "@/components/theme-color";
import { ThemeProvider } from "@/components/theme-provider";
import { SiteHeader } from "@/components/site-header";
import { SiteFooter } from "@/components/site-footer";
import { ScrollToTop } from "@/components/scroll-to-top";
import { FOCUSABLE_CHROME } from "@/lib/a11y";
import { getPublishedPosts } from "@/lib/blog";
import { navItems } from "@/lib/nav";
import { paletteItems } from "@/lib/palette";
import { ogImagePath } from "@/lib/discovery";
import { serializeJsonLd } from "@/lib/json-ld";
import { profileUrls, site } from "@/lib/site";
import "./globals.css";

/** Long-form prose only. Structure and UI stay on the sans. */
const plexSerif = IBM_Plex_Serif({
  subsets: ["latin"],
  weight: ["400", "500", "600"],
  style: ["normal", "italic"],
  display: "swap",
  variable: "--font-plex-serif",
});

/** Marginalia — annotations that read as a hand, never as body copy. */
const caveat = Caveat({
  subsets: ["latin"],
  weight: ["400", "600"],
  display: "swap",
  variable: "--font-caveat",
});

export const metadata: Metadata = {
  metadataBase: new URL(site.url),
  title: {
    default: `${site.name} — ${site.tagline}`,
    template: `%s · ${site.name}`,
  },
  description: site.description,
  openGraph: {
    title: site.name,
    description: site.description,
    url: site.url,
    siteName: site.name,
    type: "website",
    images: [{ url: ogImagePath(site.name) }],
  },
  twitter: {
    card: "summary_large_image",
    title: site.name,
    description: site.description,
    images: [ogImagePath(site.name)],
  },
  alternates: {
    // The auto-discovery link. It is what lets a reader be handed
    // `dhruv2mars.com` and find the feed on its own, which is how most people
    // subscribe — they never see `/feed.xml`. The title is what the reader
    // then files it under.
    types: {
      "application/rss+xml": [
        { url: site.rssPath, title: `${site.name} — Blog` },
      ],
    },
  },
};

export const viewport: Viewport = {
  /* The dock at the foot of the page pads itself with
     `env(safe-area-inset-bottom)`, and that variable is zero on iOS unless the
     page has opted out of the safe-area letterbox first. */
  viewportFit: "cover",
  themeColor: [
    { media: "(prefers-color-scheme: dark)", color: "#09090b" },
    { media: "(prefers-color-scheme: light)", color: "#ffffff" },
  ],
};

const jsonLd = {
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      name: site.name,
      url: site.url,
      description: site.description,
      author: { "@type": "Person", name: site.name, url: site.url },
    },
    {
      "@type": "Person",
      name: site.name,
      url: site.url,
      jobTitle: site.tagline,
      sameAs: profileUrls(),
    },
  ],
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const posts = getPublishedPosts();
  const hasPosts = posts.length > 0;

  return (
    <html
      lang="en"
      className={`preload ${GeistSans.variable} ${GeistMono.variable} ${plexSerif.variable} ${caveat.variable}`}
      suppressHydrationWarning
    >
      <body>
        {/* Two things that must be settled before the first paint: drop
            `.preload` so the stored theme never animates in from the wrong
            colour, and flag the platform so the shortcut caps render ⌘ or
            Ctrl once rather than rendering one and correcting to the other. */}
        <script
          dangerouslySetInnerHTML={{
            __html:
              "if(/Mac|iPhone|iPad|iPod/.test(navigator.platform||navigator.userAgent))document.documentElement.classList.add('os-macos');" +
              "requestAnimationFrame(function(){requestAnimationFrame(function(){document.documentElement.classList.remove('preload')})})",
          }}
        />
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
        />
        <ThemeProvider>
          <ThemeColor />
          {/* One palette for the whole shell: the header's trigger and the
              dock's are two doors onto the same dialog, so the state sits
              above both rather than inside either. */}
          <CommandPaletteProvider items={paletteItems(posts)}>
            {/* `isolate` keeps the full-bleed hairlines (which paint at -z-1)
              above the page background instead of under it. */}
            <div className="group/layout relative isolate flex min-h-[100dvh] flex-col">
              <a
                href={FOCUSABLE_CHROME.skipToContentHref}
                className="skip-link"
              >
                {FOCUSABLE_CHROME.skipToContentLabel}
              </a>
              <SiteHeader hasPosts={hasPosts} />
              <main
                id={FOCUSABLE_CHROME.mainContentId}
                tabIndex={-1}
                className="flex max-w-screen flex-1 flex-col overflow-x-clip px-2 outline-none"
              >
                {/* A flex column so a short route (404, an empty state) can grow a
                  railed spacer down to the footer instead of leaving the frame
                  hanging in a void. */}
                <div className="mx-auto flex w-full flex-1 flex-col md:max-w-3xl">
                  {children}
                </div>
              </main>

              {/* Below `sm` this is the nav and the way into the palette. It
                  is mounted here, after the content it floats over, so the tab
                  order reaches it where the eye does. */}
              <MobileDock
                items={[{ label: "Home", href: "/" }, ...navItems(hasPosts)]}
              />

              <SiteFooter />

              {/* The bottom edge of the sheet. Ninety-six pixels of the page
                dissolving into the background, masked so the fade itself
                fades out rather than ending on a line, plus a solid strip
                under the home indicator. It is what keeps the last row of
                content from butting into the edge of the glass — and on a
                phone it is what the floating palette dock sits on. */}
              <div aria-hidden className="fade-bottom">
                <div className="fade-bottom-gradient" />
                <div className="fade-bottom-rest" />
              </div>

              {/* The way back up, riding on top of that fade. */}
              <ScrollToTop />
            </div>
          </CommandPaletteProvider>
        </ThemeProvider>
        <Analytics />
        <SpeedInsights />
      </body>
    </html>
  );
}
import { ActivitySection } from "@/components/activity-section";
import { BlogSection, HOME_POST_LIMIT } from "@/components/blog-section";
import { Overview } from "@/components/overview";
import { ProfileHeader } from "@/components/profile-header";
import {
  HOME_PROJECT_LIMIT,
  ProjectsSection,
} from "@/components/projects-section";
import { getPublishedPosts } from "@/lib/blog";
import { cn } from "@/lib/utils";

/** Matches the AI Activity blob's own cache window. */
export const revalidate = 3600;

/**
 * The hatched band between panels. It is load-bearing: it is what makes the
 * page read as one continuous sheet with cut-outs rather than as stacked cards.
 */
function PanelDivider({ className }: { className?: string }) {
  return (
    <div
      aria-hidden
      className={cn(
        "stripe-divider h-(--separator-height) w-full border-x border-line",
        className,
      )}
    />
  );
}

export default function Home() {
  // Nothing empty is ever shown: with no Post published there is no Blog
  // panel, the same rule the nav and `/blog` itself follow.
  const hasPosts = getPublishedPosts().length > 0;

  return (
    <div className="[--separator-height:--spacing(8)] **:data-[slot=panel]:scroll-mt-[calc(var(--header-height)+var(--separator-height))]">
      <ProfileHeader />

      {/* The reference bands the hero off from the panels, then runs identity —
          overview, links, the contribution grid — as one uninterrupted block
          before the next band. The bands group panels; they do not separate
          every one of them. */}
      <PanelDivider />
      <Overview />
      <ActivitySection />

      <PanelDivider />
      <ProjectsSection limit={HOME_PROJECT_LIMIT} />

      {hasPosts ? (
        <>
          <PanelDivider />
          <BlogSection limit={HOME_POST_LIMIT} />
        </>
      ) : null}
      {/* No trailing divider. Bands go *between* panels; the footer opens with
          its own, and two adjacent bands read as a double border. */}
    </div>
  );
}

output.text:
"use client";

import { useMotionValueEvent, useScroll } from "motion/react";
import { useState } from "react";
import { cn } from "@/lib/utils";

/**
 * The wordmark contracts to its short form as the page moves.
 *
 * `dhruv2mars` → `d2m`: the two vowel runs are not faded out and left behind,
 * they are collapsed, so the letters that survive close the gap themselves and
 * arrive as one mark rather than three survivors. The collapse is a grid track
 * animating `1fr → 0fr` — the same trick the project rows use to open — which
 * keeps the whole thing to two CSS properties and no measurement.
 */

/** Compact past this; expand back below it. The gap is hysteresis: without it
 *  a scroll parked on the boundary would flutter the mark. */
const COMPACT_AT = 40;
const EXPAND_AT = 12;

function Drop({ children, compact }: { children: string; compact: boolean }) {
  return (
    <span
      aria-hidden
      data-compact={compact || undefined}
      className={cn(
        "grid grid-cols-[1fr] transition-[grid-template-columns,opacity] duration-350 ease-out",
        "data-compact:grid-cols-[0fr] data-compact:opacity-0",
        "motion-reduce:transition-none",
      )}
    >
      <span className="overflow-hidden">{children}</span>
    </span>
  );
}

export function SiteHeaderMark() {
  const { scrollY } = useScroll();
  const [compact, setCompact] = useState(false);

  useMotionValueEvent(scrollY, "change", (y) => {
    setCompact((was) => (was ? y > EXPAND_AT : y > COMPACT_AT));
  });

  return (
    <span
      // The accessible name lives on the link; the letters are decoration once
      // they can be pulled apart mid-word.
      className="flex items-center font-heading text-lg leading-none font-medium tracking-tight"
    >
      <span aria-hidden>d</span>
      <Drop compact={compact}>hruv</Drop>
      <span aria-hidden>2</span>
      <span aria-hidden>m</span>
      <Drop compact={compact}>ars</Drop>
    </span>
  );
}

--- short mark ---
import { cn } from "@/lib/utils";

/**
 * The short mark — what the header wordmark contracts to on scroll, and the
 * only mark small surfaces are allowed to use. It is set in the heading face
 * rather than drawn, so it is the same object as the wordmark seen from
 * further away instead of a second logo that has to be kept in agreement.
 */
export function ShortMark({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      aria-hidden
      className={cn(
        "font-heading text-sm leading-none font-medium tracking-tight select-none",
        className,
      )}
      {...props}
    >
      d2m
    </span>
  );
}

--- header ---
import Link from "next/link";
import { PaletteTrigger } from "@/components/command-palette";
import { Separator } from "@/components/separator";
import { SiteHeaderMark } from "@/components/site-header-mark";
import { SiteNav } from "@/components/site-nav";
import { ThemeToggle } from "@/components/theme-toggle";
import { FOCUSABLE_CHROME } from "@/lib/a11y";
import { navItems } from "@/lib/nav";

export function SiteHeader({ hasPosts }: { hasPosts: boolean }) {
  const items = navItems(hasPosts);

  return (
    <header className="sticky top-0 z-50 max-w-screen overflow-x-clip bg-background px-2">
      {/* `after:z-1 after:bg-border` lifts the bottom hairline above the
          content scrolling beneath it and darkens it to a real edge. */}
      <div className="screen-line-top screen-line-bottom mx-auto flex h-(--header-height) items-center gap-2 border-r border-line pr-2 after:z-1 after:bg-border sm:gap-4 md:max-w-3xl">
        <Link
          href="/"
          aria-label="Home"
          className="flex items-center pl-2 text-foreground"
        >
          {/* The wordmark alone. A glyph beside it would be a second mark
              competing with the one the hero already draws. */}
          <SiteHeaderMark />
        </Link>

        <div className="flex-1" />

        {/* Below `sm` the bar collapses to mark plus controls: the same
            routes are a thumb's reach away in the dock, and keeping them here
            cost the theme toggle its right gutter. */}
        <nav
          aria-label={FOCUSABLE_CHROME.primaryNavLabel}
          className="flex items-center gap-4 max-sm:hidden"
        >
          <SiteNav items={items} variant="header" />
        </nav>

        {/* The header trigger names a shortcut, so it goes where the nav
            goes. Below `sm` the palette puts up a thumb-reachable dock
            instead — see `MobileDock`. GitHub is not here: it is already a
            glyph in the links row, and a link that appears twice on one
            screen is one link too many. */}
        <div className="flex items-center max-sm:*:data-[slot=command-menu-trigger]:hidden">
          <Separator orientation="vertical" className="mr-2 h-5 max-sm:hidden" />
          <PaletteTrigger />
          <Separator orientation="vertical" className="mx-2 h-5" />
          <ThemeToggle />
        </div>
      </div>
    </header>
  );
}

--- globals animation refs ---
@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));
/* Margin notes are for readers with a cursor; a touch device has no room for
   them and no pointer to aim. */
@custom-variant pointer-fine (@media (pointer: fine));

/* ---------------------------------------------------------------------------
   Tokens. A neutral zinc system — no chromatic accent. Colour appears only
   where it carries meaning (links, status). `--line` is the hairline the
   whole frame is drawn with: the border colour, softened toward the
   background so a full-bleed rule reads as structure rather than a box.
--------------------------------------------------------------------------- */

:root {
  color-scheme: light;

  --background: oklch(1 0 0);
  --foreground: oklch(0.141 0.005 285.823); /* zinc-950 */

  --primary: oklch(0.141 0.005 285.823);
  --primary-foreground: oklch(0.985 0 0);

  --secondary: oklch(0.967 0.001 286.375); /* zinc-100 */
  --secondary-foreground: oklch(0.141 0.005 285.823);

  --muted: oklch(0.967 0.001 286.375); /* zinc-100 — a surface */
  --muted-foreground: oklch(0.552 0.016 285.938); /* zinc-500 */

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.141 0.005 285.823);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.141 0.005 285.823);

  --accent: oklch(0.967 0.001 286.375); /* zinc-100 */
  --accent-muted: color-mix(in oklab, var(--accent) 50%, transparent);
  --accent-foreground: oklch(0.21 0.006 285.885);

  --border: oklch(0.92 0.004 286.32); /* zinc-200 */
  --line: color-mix(in oklab, var(--border) 64%, var(--background));
  --input: oklch(0.92 0.004 286.32);
  --ring: oklch(0.705 0.015 286.067); /* zinc-400 */

  --info: oklch(0.67 0.17 244.98);
  --success: oklch(0.723 0.219 149.579);
  --destructive: oklch(0.577 0.245 27.325);
  --link: oklch(0.488 0.243 264.376); /* blue-700 */

  --surface: oklch(0.985 0 0);
  --surface-foreground: oklch(0.141 0.005 285.823);

  --code: var(--background);
  --code-foreground: var(--foreground);
  --code-number: oklch(0.24 0.01 0 / 0.3);
  --code-highlight: oklch(0.49 0.18 257.61 / 0.06);

  --selection: oklch(0.141 0.005 285.823);
  --selection-foreground: oklch(0.985 0 0);

  --header-height: --spacing(14);
  --fade-bottom-height: --spacing(24);
}

.dark {
  color-scheme: dark;

  --background: oklch(0.141 0.005 285.823);
  --foreground: oklch(0.985 0 0);

  --primary: oklch(0.985 0 0);
  --primary-foreground: oklch(0.141 0.005 285.823);

  --secondary: oklch(0.274 0.006 286.033); /* zinc-800 */
  --secondary-foreground: oklch(0.985 0 0);

  --muted: oklch(0.274 0.006 286.033);
  --muted-foreground: oklch(0.705 0.015 286.067); /* zinc-400 */

  --card: oklch(0.21 0.006 285.885); /* zinc-900 */
  --card-foreground: oklch(0.985 0 0);

  --popover: oklch(0.21 0.006 285.885);
  --popover-foreground: oklch(0.985 0 0);

  --accent: oklch(0.274 0.006 286.033);
  --accent-muted: color-mix(in oklab, var(--accent) 20%, transparent);
  --accent-foreground: oklch(0.985 0 0);

  --border: oklch(0.274 0.006 286.033);
  --input: lab(100% 0 0 / 0.15);
  --ring: oklch(0.552 0.016 285.938);

  --success: oklch(0.723 0.219 149.579);
  --destructive: oklch(0.505 0.213 27.518);
  --link: oklch(0.623 0.214 259.815); /* blue-500 */

  --surface: oklch(0.21 0.006 285.885);
  --surface-foreground: oklch(0.985 0 0);

  --code-number: oklch(0.43 0 0);
  --code-highlight: oklch(0.71 0.24 42.36 / 0.06);

  --selection: oklch(0.985 0 0);
  --selection-foreground: oklch(0.141 0.005 285.823);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);

  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);

  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);

  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);

  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --color-accent: var(--accent);
  --color-accent-muted: var(--accent-muted);
  --color-accent-foreground: var(--accent-foreground);

  --color-border: var(--border);
  --color-line: var(--line);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-info: var(--info);
  --color-success: var(--success);
  --color-destructive: var(--destructive);
  --color-link: var(--link);

  --color-surface: var(--surface);
  --color-surface-foreground: var(--surface-foreground);

  --color-code: var(--code);
  --color-code-foreground: var(--code-foreground);
  --color-code-number: var(--code-number);
  --color-code-highlight: var(--code-highlight);

  --color-selection: var(--selection);
  --color-selection-foreground: var(--selection-foreground);

  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, SFMono-Regular, monospace;
  --font-heading: var(--font-sans);
  --font-serif: var(--font-plex-serif), ui-serif, Georgia, serif;
  --font-handwriting: var(--font-caveat), var(--font-sans);

  --default-mono-font-feature-settings: "ss11" 1, "zero" 1, "tnum" 1;

  --ease-out-quint: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-io: cubic-bezier(0.65, 0, 0.35, 1);
}

/* ---------------------------------------------------------------------------
   Utilities. The frame system: hairlines that span the viewport rather than
   stopping at the content rail, and diagonal hatching for the gaps between
   panels.
--------------------------------------------------------------------------- */

@utility link {
  @apply decoration-1 underline-offset-3 hover:underline;
}

@utility link-underline {
  @apply underline decoration-current/30 decoration-1 underline-offset-3 transition-colors hover:decoration-current;
}

@utility screen-line-top {
  @apply relative;

  &:before {
    content: "";
    @apply absolute top-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-line-bottom {
  @apply relative;

  &:after {
    content: "";
    @apply absolute bottom-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-dashed-line-top {
  @apply screen-line-top;

  &:before {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-dashed-line-bottom {
  @apply screen-line-bottom;

  &:after {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-line-top-none {
  @apply before:content-none;
}

@utility screen-line-bottom-none {
  @apply after:content-none;
}
}

@utility diagonal-stripes {
  @apply [--pattern-foreground:var(--color-line)]/56;
  @apply bg-[repeating-linear-gradient(315deg,var(--pattern-foreground)_0,var(--pattern-foreground)_1px,transparent_0,transparent_50%)] bg-size-[10px_10px];
}

@utility stripe-divider {
  @apply relative h-8;

  &:before {
    content: "";
    @apply absolute left-[-100vw] -z-1 h-full w-[200vw] diagonal-stripes;
  }
}

/* Pointer-coarse devices get a 24px-minimum hit area without a 24px box. */
@utility extend-touch-target {
  @media (pointer: coarse) {
    @apply relative touch-manipulation after:absolute after:-inset-2;
  }
}

/* The quiet control: a toolbar button that is an icon at rest and a surface
   only once it is under the pointer. Used by every action on a post — copy,
   share, the two arrows — so the row reads as one set rather than four
   buttons that happen to sit together. */
@utility action-button {
  @apply inline-flex h-8 min-w-8 items-center justify-center gap-1.5 rounded-lg px-2 text-sm text-muted-foreground transition-colors select-none active:scale-[0.98] hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40 dark:hover:bg-accent/50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0;
}

/* ---------------------------------------------------------------------------
   Base
--------------------------------------------------------------------------- */

@layer base {
  *,
  ::after,
  ::before,
  ::backdrop,
  ::file-selector-button {
    @apply border-border outline-ring/50;
  }

  html {
    -webkit-text-size-adjust: 100%;
    scroll-behavior: smooth;
  }

  body {
    @apply bg-background text-foreground antialiased;
    font-synthesis-weight: none;
    text-rendering: optimizeLegibility;
  }

  ::selection {
    @apply bg-selection text-selection-foreground;
  }

  /* Suppress every transition until after first paint so the stored theme
     never animates in from the wrong colour. */
  .preload *,
  .preload *::before,
  .preload *::after {
    transition: none !important;
    animation: none !important;
  }

  ::-webkit-scrollbar {
    width: 5px;
    height: 5px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: var(--border);
    border-radius: 5px;
  }
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }

  [id] {
    @apply scroll-mt-18;
  }

  /* The field draws its own clear button, in the site's own glyph. WebKit
     offers a second one, in its own, and two crosses in one input is one
     too many. */
  input[type="search"]::-webkit-search-cancel-button {
    -webkit-appearance: none;
    appearance: none;
  }

  /* One focus ring for the whole site. Every keyboard affordance — header
     buttons, palette rows, inline links, the mosaic — draws the same 2px
     outline at the same offset, so focus never changes shape as it moves.
     Components that need a different shape opt out with their own `outline`,
     not with their own ring colour. */
  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}

/* ---------------------------------------------------------------------------
   Chrome
--------------------------------------------------------------------------- */

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 50%;
  z-index: 90;
  translate: -50% -300%;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--background);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  transition: translate 200ms var(--ease-out-quint);
}
.skip-link:focus-visible {
  translate: -50% 0;
}

/* ---------------------------------------------------------------------------
   Typeset — the two long-form measures. `--typeset-flow` is the vertical
   rhythm between blocks, expressed in the block's own em so it scales with
   the measure rather than the root.
--------------------------------------------------------------------------- */

.typeset {
  --typeset-size: 1rem;
  --typeset-leading: 1.65;
  --typeset-flow: 1.25em;

  font-size: var(--typeset-size);
  line-height: var(--typeset-leading);
  text-wrap: pretty;
}

.typeset > * + * {
  margin-top: var(--typeset-flow);
}

.typeset-description {
  --typeset-size: 15px;
  --typeset-leading: 1.6;
  --typeset-flow: 1em;
}

.typeset-timescale {
  --typeset-size: 0.875rem;
  --typeset-leading: 1.5;
  --typeset-flow: 1em;
}

  from {
    opacity: 0;
    transform: translateY(8px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes dock-sheet-out {
  from {
    opacity: 1;
    transform: none;
  }
  to {
    opacity: 0;
    transform: translateY(8px) scale(0.95);
  }
}

.dock-sheet {
  transform-origin: 50% calc(100% + 8px);
  animation: dock-sheet-in 100ms var(--ease-out-quint) both;
}

.dock-sheet[data-state="closed"] {
  animation: dock-sheet-out 100ms var(--ease-out-quint) both;
}

/* ---------------------------------------------------------------------------
   Project disclosure. A row opens by growing its own track from nothing, so
   the record can be one line or five and the row never has to be measured
   first. `visibility` rather than `display`, so the closed record stays out of
   the tab order and off the screen reader without killing the transition.
--------------------------------------------------------------------------- */
.project-details {
  grid-template-rows: 0fr;
  visibility: hidden;
  transition:
    grid-template-rows 240ms var(--ease-out-quint),
    visibility 240ms;
}

.project-details[data-open="true"] {
  grid-template-rows: 1fr;
  visibility: visible;
}

/* ---------------------------------------------------------------------------
   Reduced motion: movement goes, colour feedback stays.
--------------------------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
  }
  .project-details {
    transition: none;
  }
  .activity-cell,
  .palette-panel,
  .palette-backdrop,
  .dock-sheet {
    animation: none !important;
    opacity: 1;
    transform: none;
  }
}

