                            name.layer,
                            timingType
                        )
                        const transitionName =
                            timingType === "group" ? "layout" : ""
                        let animationTransition = resolveLayerTransition(
                            targetDefinition,
                            timingType,
                            transitionName,
                            index === -1 ? 0 : index,
                            total
                        )

