                    for (const corner of cornerRadiusProps) {
                        // `||` (not `??`) so an empty measurement falls back to
                        // the other snapshot rather than an invalid keyframe.
                        const from =
                            entry.old?.radii[corner] ||
                            entry.new?.radii[corner] ||
                            "0px"
                        const to =
                            entry.new?.radii[corner] ||
                            entry.old?.radii[corner] ||
