    React.PropsWithChildren<Props>
> = ({ children, id, inherit = true }) => {
    const layoutGroupContext = useContext(LayoutGroupContext)
    const deprecatedLayoutGroupContext = useContext(
        DeprecatedLayoutGroupContext
