        transform.match(/^matrix\((.*)\)$/u)
    if (!match) return null

    const v = match[1].split(",").map(Number)
    const is3d = transform.startsWith("matrix3d")
    const a = v[0],
        b = v[1]
    const c = is3d ? v[4] : v[2]
    const d = is3d ? v[5] : v[3]

    const det = a * d - b * c
