export type SocialLink = {
  label: "X" | "GitHub" | "LinkedIn" | "Email";
  href: string;
};

export const site = {
  name: "Dhruv Sharma",
  handle: "Dhruv2mars",
  /** The role, shown under the name. Lowercase on purpose. */
  tagline: "agentic engineer",
  /**
   * The role line said more than one way. The first is the canonical one — it
   * is what `tagline` carries into metadata and structured data, where nothing
   * can rotate — and the rest widen it without the hero growing a paragraph.
   */
  flipSentences: [
    "agentic engineer",
    "prototyper",
    "tooling for coding agents",
    "local-first by default",
  ] as const,
  /**
   * How the name sounds. `audio` is the answer — a recording of the name being
   * said — and `phonetic` is the same answer written down, shown on the button
   * for anyone who would rather read it. With no recording the button is not
   * drawn: a synthesised English voice has neither the breathy d nor the
   * retroflex v, so it says a different name confidently, which is worse than
   * silence.
   */
  pronunciation: {
    phonetic: "/dʱruːʋ ˈʃərmə/",
    audio: "/audio/dhruv-sharma.mp3" as string | null,
  },
  /**
   * The one-line description search results, feed readers and the install
   * manifest read. It is not rendered on the page: the hero already says the
   * name and the role, and a third line under them was prose the page did not
   * need. See `app/layout.tsx`.
   */
  description:
    "I build tooling for coding agents — repro harnesses, queues, local-first inference — and ship with them every day.",
  url: "https://dhruv2mars.com",
  /**
   * No portrait exists yet. The profile header reserves this slot and renders
   * a monogram at the same size; setting this to an image path is the only
   * change needed to fill it, with no layout shift.
   */
  avatar: null as string | null,
  socials: [
    { label: "X", href: "https://x.com/Dhruv2mars" },
    { label: "GitHub", href: "https://github.com/Dhruv2mars" },
    { label: "LinkedIn", href: "https://linkedin.com/in/dhruv2mars" },
    { label: "Email", href: "mailto:Dhruv2mars@gmail.com" },
  ] as const satisfies readonly SocialLink[],
  rssPath: "/feed.xml",
} as const;

/** Socials minus mailto, for `sameAs` in structured data. */
export function profileUrls(): string[] {
  return site.socials
    .filter((s) => !s.href.startsWith("mailto:"))
    .map((s) => s.href);
}
/**
 * Keyboard / focus chrome contracts for the Editorial shell.
 * Used by Primary nav, theme control, and outbound Project/Post links.
 */
export const FOCUSABLE_CHROME = {
  primaryNavLabel: "Primary",
  skipToContentHref: "#main-content",
  skipToContentLabel: "Skip to content",
  mainContentId: "main-content",
} as const;

/** A control is keyboard-reachable when it can receive focus and has a name. */
export function isKeyboardReachableControl(options: {
  hasAccessibleName: boolean;
  tabbable: boolean;
}): boolean {
  return options.tabbable && options.hasAccessibleName;
}
import { Rss, SOCIAL_ICONS } from "@/components/icons";
import { SiteWordmark } from "@/components/site-wordmark";
import { site } from "@/lib/site";

/**
 * The profiles, minus the mailbox.
 *
 * The overview's "say hi" row is the directory — it is the place that answers
 * "how do I reach this person", so it carries every way, email included. The
 * footer is a signature, and a signature does not repeat the directory: it
 * carries the three places the work lives, and the feed, which is a property
 * of the site rather than of the person and so belongs here and nowhere else.
 */
const FOOTER_SOCIALS = site.socials.filter(
  (social) => !social.href.startsWith("mailto:"),
);

export function SiteFooter() {
  return (
    <footer className="max-w-screen overflow-x-clip px-2">
      <div className="mx-auto border-x border-line md:max-w-3xl">
        <div className="screen-line-top screen-line-bottom">
          <div className="stripe-divider h-12" />
        </div>

        {/* One closing line: the copyright reads left, the glyphs read right,
            and on a phone they stack centred rather than squeezing. */}
        <div className="screen-line-top screen-line-bottom flex flex-col items-center justify-center gap-x-4 gap-y-3 px-4 py-3 text-sm text-muted-foreground sm:flex-row sm:justify-between">
          {/* The mark, not the legal name: the wordmark below signs the page
              and this line should agree with it. */}
          <span>
            &copy; {new Date().getFullYear()} {site.handle.toLowerCase()}.
          </span>

          {/* Four glyphs on one gutter. The rules that used to stand between
              them were 16px of hairline at 12px intervals — texture, at this
              size, not structure. */}
          <nav aria-label="Elsewhere" className="flex items-center gap-4">
            {FOOTER_SOCIALS.map((social) => {
              const Glyph = SOCIAL_ICONS[social.label];
              return (
                <a
                  key={social.label}
                  href={social.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={social.label}
                  title={social.label}
                  className="flex items-center transition-colors hover:text-foreground"
                >
                  <Glyph className="size-4" />
                </a>
              );
            })}
            <a
              href={site.rssPath}
              aria-label="RSS feed"
              title="RSS feed — paste this address into a feed reader"
              className="flex items-center transition-colors hover:text-foreground"
            >
              <Rss className="size-4" />
            </a>
          </nav>
        </div>

        {/* The name at plate scale, last, the way a colophon signs a book.
            Nothing follows it: a list of links under the signature would read
            as a caption on the drawing. */}
        <div className="screen-line-bottom px-4 py-8 sm:px-6 sm:py-10">
          <SiteWordmark
            text={site.handle.toLowerCase()}
            className="w-full text-foreground"
          />
        </div>

        {/* Run-out. The fixed bottom fade is the last thing every scroll meets,
            so the sheet has to keep going for at least its height past the last
            row — otherwise the last line reads through the fade. The
            reference spends this space on a drawing; we spend it on rail —
            the wrapper's own, which already runs the height of the footer. */}
        <div aria-hidden className="h-(--fade-bottom-height)" />

        <div className="pb-[env(safe-area-inset-bottom,0)]" />
      </div>
    </footer>
  );
}

