    <div
      onPointerMove={handleMove}
      onPointerLeave={() => ratio.set(0.5)}
      className={className}
    >
      <svg
        aria-hidden
        viewBox={`0 0 ${width} ${ROWS}`}
        className="w-full"
        preserveAspectRatio="xMidYMid meet"
      >
        <defs>
          <g id={cellsId}>
            {cells.map((cell) => (
              <rect
                key={`${cell.x}-${cell.y}`}
                x={cell.x + 0.08}
                y={cell.y + 0.08}
                width={0.84}
                height={0.84}
                rx={0.14}
