"use client";

import { useMotionValueEvent, useScroll } from "motion/react";
import { useState } from "react";
import { cn } from "@/lib/utils";

/**
 * The wordmark contracts to its short form as the page moves.
 *
 * `dhruv2mars` → `d2m`: the two vowel runs are not faded out and left behind,
 * they are collapsed, so the letters that survive close the gap themselves and
 * arrive as one mark rather than three survivors. The collapse is a grid track
 * animating `1fr → 0fr` — the same trick the project rows use to open — which
 * keeps the whole thing to two CSS properties and no measurement.
 */

/** Compact past this; expand back below it. The gap is hysteresis: without it
 *  a scroll parked on the boundary would flutter the mark. */
const COMPACT_AT = 40;
const EXPAND_AT = 12;

function Drop({ children, compact }: { children: string; compact: boolean }) {
  return (
    <span
      aria-hidden
      data-compact={compact || undefined}
      className={cn(
        "grid grid-cols-[1fr] transition-[grid-template-columns,opacity] duration-350 ease-out",
        "data-compact:grid-cols-[0fr] data-compact:opacity-0",
        "motion-reduce:transition-none",
      )}
    >
      <span className="overflow-hidden">{children}</span>
    </span>
  );
}

export function SiteHeaderMark() {
  const { scrollY } = useScroll();
  const [compact, setCompact] = useState(false);

  useMotionValueEvent(scrollY, "change", (y) => {
    setCompact((was) => (was ? y > EXPAND_AT : y > COMPACT_AT));
  });

  return (
    <span
      // The accessible name lives on the link; the letters are decoration once
      // they can be pulled apart mid-word.
      className="flex items-center font-heading text-lg leading-none font-medium tracking-tight"
    >
      <span aria-hidden>d</span>
      <Drop compact={compact}>hruv</Drop>
      <span aria-hidden>2</span>
      <span aria-hidden>m</span>
      <Drop compact={compact}>ars</Drop>
    </span>
  );
}
import Link from "next/link";
import { PaletteTrigger } from "@/components/command-palette";
import { Separator } from "@/components/separator";
import { SiteHeaderMark } from "@/components/site-header-mark";
import { SiteNav } from "@/components/site-nav";
import { ThemeToggle } from "@/components/theme-toggle";
import { FOCUSABLE_CHROME } from "@/lib/a11y";
import { navItems } from "@/lib/nav";

export function SiteHeader({ hasPosts }: { hasPosts: boolean }) {
  const items = navItems(hasPosts);

  return (
    <header className="sticky top-0 z-50 max-w-screen overflow-x-clip bg-background px-2">
      {/* `after:z-1 after:bg-border` lifts the bottom hairline above the
          content scrolling beneath it and darkens it to a real edge. */}
      <div className="screen-line-top screen-line-bottom mx-auto flex h-(--header-height) items-center gap-2 border-r border-line pr-2 after:z-1 after:bg-border sm:gap-4 md:max-w-3xl">
        <Link
          href="/"
          aria-label="Home"
          className="flex items-center pl-2 text-foreground"
        >
          {/* The wordmark alone. A glyph beside it would be a second mark
              competing with the one the hero already draws. */}
          <SiteHeaderMark />
        </Link>

        <div className="flex-1" />

        {/* Below `sm` the bar collapses to mark plus controls: the same
            routes are a thumb's reach away in the dock, and keeping them here
            cost the theme toggle its right gutter. */}
        <nav
          aria-label={FOCUSABLE_CHROME.primaryNavLabel}
          className="flex items-center gap-4 max-sm:hidden"
        >
          <SiteNav items={items} variant="header" />
        </nav>

        {/* The header trigger names a shortcut, so it goes where the nav
            goes. Below `sm` the palette puts up a thumb-reachable dock
            instead — see `MobileDock`. GitHub is not here: it is already a
            glyph in the links row, and a link that appears twice on one
            screen is one link too many. */}
        <div className="flex items-center max-sm:*:data-[slot=command-menu-trigger]:hidden">
          <Separator orientation="vertical" className="mr-2 h-5 max-sm:hidden" />
          <PaletteTrigger />
          <Separator orientation="vertical" className="mx-2 h-5" />
          <ThemeToggle />
        </div>
      </div>
    </header>
  );
}
import { cn } from "@/lib/utils";

/**
 * The short mark — what the header wordmark contracts to on scroll, and the
 * only mark small surfaces are allowed to use. It is set in the heading face
 * rather than drawn, so it is the same object as the wordmark seen from
 * further away instead of a second logo that has to be kept in agreement.
 */
export function ShortMark({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      aria-hidden
      className={cn(
        "font-heading text-sm leading-none font-medium tracking-tight select-none",
        className,
      )}
      {...props}
    >
      d2m
    </span>
  );
}
"use client";

import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import { useId, type PointerEvent as ReactPointerEvent } from "react";

/**
 * The name, drawn rather than set: a 7-row bitmap on the same square cell the
 * activity grid uses, so the page closes on the unit it opened with.
 *
 * Two passes over one cell set. The first is a hairline outline that is always
 * there, drawn in the mark's own ink at a third strength — the name is legible
 * on the page whether or not anyone touches it.
 * The second fills those same cells through a gradient that is transparent
 * until 62.5% of its own length and solid after, and the gradient's near end is
 * tied to the pointer. So the ink is not painted *at* the cursor; it runs away
 * from it, and moving across the mark tips a wash of it from one side of the
 * name to the other.
 *
 * At rest the near end sits at the horizontal middle, which makes the gradient
 * vertical: the bottom of the letters is inked and the tops fade to outline, so
 * the signature reads as filling up rather than as waiting for a mouse. A
 * phone, which never sends a pointer, gets that resting state and nothing else
 * — which is the point of choosing a resting state that stands on its own.
 *
 * The cells are declared once in `<defs>` and drawn twice with `<use>`, so the
 * markup carries ~140 rects rather than ~280.
 */
const GLYPHS: Readonly<Record<string, readonly string[]>> = {
  a: [".....", ".....", ".###.", "....#", ".####", "#...#", ".####"],
  d: ["....#", "....#", ".####", "#...#", "#...#", "#...#", ".####"],
  h: ["#....", "#....", "#.##.", "##..#", "#...#", "#...#", "#...#"],
  m: [".....", ".....", "##.##", "#.#.#", "#.#.#", "#.#.#", "#.#.#"],
  r: [".....", ".....", "#.##.", "##..#", "#....", "#....", "#...."],
  s: [".....", ".....", ".####", "#....", ".###.", "....#", "####."],
  u: [".....", ".....", "#...#", "#...#", "#...#", "#..##", ".##.#"],
  v: [".....", ".....", "#...#", "#...#", "#...#", ".#.#.", "..#.."],
  "2": [".###.", "#...#", "....#", "...#.", "..#..", ".#...", "#####"],
};

const ROWS = 7;
/** One blank column between letters — the grid's own gutter, not kerning. */
const TRACKING = 1;

/**
 * Where the wash stops being nothing and starts being ink, measured along the
 * gradient rather than across the mark. The reference's number, and it is the
 * one that makes the resting state work: 0.625 of seven rows puts the tide line
 * between the fifth and sixth, which is where these letterforms have their
 * waist.
 */
const INK_OFFSET = 0.625;

/** Heavy enough that the wash lags the pointer instead of tracking it. */
const SPRING = { stiffness: 150, damping: 25 } as const;

function layout(text: string) {
  const cells: { x: number; y: number }[] = [];
  let cursor = 0;

  for (const char of text) {
    const glyph = GLYPHS[char];
    if (!glyph) continue;
    for (let y = 0; y < glyph.length; y++) {
      for (let x = 0; x < glyph[y].length; x++) {
        if (glyph[y][x] === "#") cells.push({ x: cursor + x, y });
      }
    }
    cursor += glyph[0].length + TRACKING;
  }

  return { cells, width: Math.max(cursor - TRACKING, 0) };
}

export function SiteWordmark({
  text,
  className,
}: {
  text: string;
  className?: string;
}) {
  // `useId` returns a value fenced in characters that are legal in an HTML id
  // but not in a CSS selector, and `fill="url(#…)"` is read as one. Stripping
  // them back to the counter keeps the uniqueness and loses the hazard.
  const id = useId().replace(/[^a-zA-Z0-9-]/g, "");
  const cellsId = `${id}-cells`;
  const inkId = `${id}-ink`;

  const { cells, width } = layout(text);
  const reduced = useReducedMotion();

  /** The pointer as a fraction of the mark's width. Centre is the rest. */
  const ratio = useMotionValue(0.5);
  const x1 = useSpring(useTransform(ratio, [0, 1], [0, width]), SPRING);

  const handleMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (reduced) return;
    const box = event.currentTarget.getBoundingClientRect();
    if (box.width === 0) return;
    ratio.set((event.clientX - box.left) / box.width);
  };

  return (
    <div
      onPointerMove={handleMove}
      onPointerLeave={() => ratio.set(0.5)}
      className={className}
    >
      <svg
        aria-hidden
        viewBox={`0 0 ${width} ${ROWS}`}
        className="w-full"
        preserveAspectRatio="xMidYMid meet"
      >
        <defs>
          <g id={cellsId}>
            {cells.map((cell) => (
              <rect
                key={`${cell.x}-${cell.y}`}
                x={cell.x + 0.08}
                y={cell.y + 0.08}
                width={0.84}
                height={0.84}
                rx={0.14}
              />
            ))}
          </g>

          {/* The far end is pinned to the foot of the mark's midline, so the
              pointer only ever swings the near end around it. `userSpaceOnUse`
              because the near end is a coordinate, not a fraction of a box. */}
          <motion.linearGradient
            id={inkId}
            x1={x1}
            y1={0}
            x2={width / 2}
            y2={ROWS}
            gradientUnits="userSpaceOnUse"
          >
            <stop
              offset={INK_OFFSET}
              stopColor="currentColor"
              stopOpacity={0}
            />
            <stop offset={1} stopColor="currentColor" />
          </motion.linearGradient>
        </defs>

        {/* The outline carries the name on its own, so it is drawn in the
            mark's own ink at low opacity rather than in the hairline border
            token: `--line` is a rule between panels, and a rule that reads
            against a panel disappears against the page. At a tenth of a cell
            it is still a hairline; it is simply a visible one. */}
        <use
          href={`#${cellsId}`}
          fill="none"
          stroke="currentColor"
          strokeOpacity={0.32}
          strokeWidth={0.09}
        />
        <use href={`#${cellsId}`} fill={`url(#${inkId})`} />
      </svg>
    </div>
  );
}
/**
 * The short mark as a standalone SVG, for the two places React cannot reach:
 * the home-screen icon and the share card, both rasterised at build time by
 * satori, which can mount neither `ShortMark` nor inherit `currentColor`.
