/**
 * Scroll thresholds for the compact header mark.
 *
 * The wider gap prevents the wordmark from fluttering when a scroll settles
 * near the boundary. Keep this logic separate from Motion so its edge cases
 * can be tested without a browser.
 */
export const HEADER_MARK_COMPACT_AT = 40;
export const HEADER_MARK_EXPAND_AT = 12;

export function nextHeaderMarkCompactState(
  scrollY: number,
  compact: boolean,
): boolean {
  return compact
    ? scrollY > HEADER_MARK_EXPAND_AT
    : scrollY > HEADER_MARK_COMPACT_AT;
}

